class Solution:
    def minimumArrayLength(self, nums):
        n = len(nums)
        m = min(nums)
        for x in nums:
            if x % m != 0:
                return 1
        c = nums.count(m)
        if 2 * c <= n:
            return 1
        return (2 * c - n + 1) // 2

