class Solution {
public:
    int minimumArrayLength(vector<int>& nums) {
        int n = nums.size();
        int m = *min_element(nums.begin(), nums.end());
        for (int x : nums)
            if (x % m != 0) return 1;
        long long c = count(nums.begin(), nums.end(), m);
        if (2 * c <= n) return 1;
        return (2 * c - n + 1) / 2;
    }
};

