class Solution {
    public int minimumArrayLength(int[] nums) {
        int n = nums.length;
        int m = Integer.MAX_VALUE;
        for (int x : nums) m = Math.min(m, x);
        for (int x : nums)
            if (x % m != 0) return 1;
        int c = 0;
        for (int x : nums) if (x == m) c++;
        if (2L * c <= n) return 1;
        return (2 * c - n + 1) / 2;
    }
}

