var minimumArrayLength = function(nums) {
    const n = nums.length;
    const m = Math.min(...nums);
    for (const x of nums)
        if (x % m !== 0) return 1;
    const c = nums.filter(x => x === m).length;
    if (2 * c <= n) return 1;
    return Math.floor((2 * c - n + 1) / 2);
};

